#!/usr/bin/env bash
# Regenerates src/tests/lint/fixtures.ts (test certificates for the linter).
# Requires OpenSSL >= 3.4 (for -not_before / -not_after).
# Keys are freshly generated on every run, so the output differs each time;
# commit the regenerated file and update any test literals that depend on it.
set -euo pipefail

OPENSSL="${OPENSSL:-openssl}"
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
OUT="$ROOT/src/tests/lint/fixtures.ts"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
cd "$WORK"

# Test root CA
"$OPENSSL" req -x509 -newkey rsa:2048 -nodes -keyout ca.key -out ca.pem -subj "/C=JP/O=Lint Test/CN=Lint Test Root CA" \
  -not_before 20250101000000Z -not_after 20351231235959Z -set_serial 0x01 -sha256 \
  -addext "basicConstraints=critical,CA:TRUE" -addext "keyUsage=critical,keyCertSign,cRLSign" 2>/dev/null

sign() { # name csr extfile serial not_before not_after digest
  local ext_args=()
  [ -n "$3" ] && ext_args=(-extfile "$3")
  "$OPENSSL" x509 -req -in "$2" -CA ca.pem -CAkey ca.key -out "$1.pem" ${ext_args[@]+"${ext_args[@]}"} \
    -set_serial "$4" -not_before "$5" -not_after "$6" "-$7" 2>/dev/null
}

# 1. Publicly-trusted style RSA leaf (BR subscriber profile)
"$OPENSSL" req -new -newkey rsa:2048 -nodes -keyout /dev/null -out public.csr -subj "/CN=www.example.com" 2>/dev/null
cat > public.ext <<'EOF'
subjectAltName=DNS:www.example.com,DNS:example.com
extendedKeyUsage=serverAuth
keyUsage=critical,digitalSignature,keyEncipherment
basicConstraints=critical,CA:FALSE
certificatePolicies=2.23.140.1.2.1
authorityInfoAccess=OCSP;URI:http://ocsp.example.test,caIssuers;URI:http://ca.example.test/ca.der
crlDistributionPoints=URI:http://crl.example.test/ca.crl
authorityKeyIdentifier=keyid
1.3.6.1.4.1.11129.2.4.2=DER:04020000
EOF
sign public public.csr public.ext 0x5A1B2C3D4E5F60718293A4B5C6D7E8F9 20260401000000Z 20260629235959Z sha256

# 2. Private-CA style ECDSA P-256 leaf
"$OPENSSL" req -new -newkey ec -pkeyopt ec_paramgen_curve:P-256 -nodes -keyout /dev/null -out private.csr -subj "/O=Example Corp/CN=app.corp" 2>/dev/null
cat > private.ext <<'EOF'
subjectAltName=DNS:app.corp,DNS:*.internal.example,IP:10.0.0.5,IP:2001:db8::1
extendedKeyUsage=serverAuth,clientAuth
keyUsage=critical,digitalSignature
basicConstraints=critical,CA:FALSE
authorityKeyIdentifier=keyid
EOF
sign private private.csr private.ext 0xC3A5F00D 20260101000000Z 20271231235959Z sha256

# 3. Self-signed certificate as produced by a bare `openssl req -x509`
"$OPENSSL" req -x509 -newkey rsa:2048 -nodes -keyout /dev/null -out selfsigned.pem -subj "/CN=localhost" \
  -addext "subjectAltName=DNS:localhost" -not_before 20260301000000Z -not_after 20290301000000Z -set_serial 0x0B -sha256 2>/dev/null

# 4. Legacy leaf: X.509 v1, RSA 1024, SHA-1
"$OPENSSL" req -x509v1 -newkey rsa:1024 -nodes -keyout /dev/null -out legacy.pem -subj "/CN=legacy.example.com" \
  -CA ca.pem -CAkey ca.key -set_serial 0x02 -not_before 20260101000000Z -not_after 20260401000000Z -sha1 2>/dev/null

# 5. Ed25519 leaf
"$OPENSSL" req -new -newkey ed25519 -nodes -keyout /dev/null -out ed25519.csr -subj "/CN=ed.example.com" 2>/dev/null
cat > ed25519.ext <<'EOF'
subjectAltName=DNS:ed.example.com
extendedKeyUsage=serverAuth
EOF
sign ed25519 ed25519.csr ed25519.ext 0x03 20260101000000Z 20260301000000Z sha256

emit() { # const_name file description
  printf '\n// %s\nexport const %s = `%s`;\n' "$3" "$1" "$(cat "$2")"
}

{
  echo '// Generated by scripts/gen-lint-fixtures.sh — do not edit by hand.'
  emit CA_CERT ca.pem 'Test root CA (CA:TRUE, keyCertSign)'
  emit PUBLIC_RSA_LEAF public.pem 'BR-style RSA leaf: 2026-04-01..2026-06-29T23:59:59Z, DV policy, OCSP+CRL, SCT'
  emit PRIVATE_EC_LEAF private.pem 'Private-CA ECDSA P-256 leaf: 2026-01-01..2027-12-31T23:59:59Z, serverAuth+clientAuth'
  emit SELF_SIGNED_DEFAULT selfsigned.pem 'Bare `openssl req -x509`: self-signed, CA:TRUE, no keyUsage/EKU'
  emit LEGACY_V1_SHA1 legacy.pem 'X.509 v1, RSA 1024, sha1WithRSAEncryption'
  emit ED25519_LEAF ed25519.pem 'Ed25519 leaf with serverAuth'
} > "$OUT"

echo "wrote $OUT"
